internal val COUNTRY_NAMES_TH: String =
    "root\u001F01อันดอร์รา\u001Eสหรัฐอาหรับเอมิเรตส์\u001Eอัฟกานิสถาน\u001Eแอนติกาและบาร์บูดา\u001Eแองกวิลลา\u001Eแอลเบเนีย\u001Eอาร์เมเนีย\u001Eแองโกลา\u001Eแอนตาร์กติกา\u001Eอาร์เจนตินา\u001Eอเมริกันซามัว\u001Eออสเตรีย\u001Eออสเตรเลีย\u001Eอารูบา\u001Eหมู่เกาะโอลันด์\u001Eอาเซอร์ไบจาน\u001Eบอสเนียและเฮอร์เซโกวีนา\u001Eบาร์เบโดส\u001Eบังกลาเทศ\u001Eเบลเยียม\u001Eบูร์กินาฟาโซ\u001Eบัลแกเรีย\u001Eบาห์เรน\u001Eบุรุนดี\u001Eเบนิน\u001Eเซนต์บาร์เธเลมี\u001Eเบอร์มิวดา\u001Eบรูไน\u001Eโบลิเวีย\u001Eเนเธอร์แลนด์แคริบเบียน\u001Eบราซิล\u001Eบาฮามาส\u001Eภูฏาน\u001Eเกาะบูเว\u001Eบอตสวานา\u001Eเบลารุส\u001Eเบลีซ\u001Eแคนาดา\u001Eหมู่เกาะโคโคส (คีลิง)\u001Eคองโก - กินชาซา\u001Eสาธารณรัฐแอฟริกากลาง\u001Eคองโก - บราซซาวิล\u001Eสวิตเซอร์แลนด์\u001Eโกตดิวัวร์\u001Eหมู่เกาะคุก\u001Eชิลี\u001Eแคเมอรูน\u001Eจีน\u001Eโคลอมเบีย\u001Eคอสตาริกา\u001Eคิวบา\u001Eเคปเวิร์ด\u001Eคูราเซา\u001Eเกาะคริสต์มาส\u001Eไซปรัส\u001Eเช็ก\u001Eเยอรมนี\u001Eจิบูตี\u001Eเดนมาร์ก\u001Eโดมินิกา\u001Eสาธารณรัฐโดมินิกัน\u001Eแอลจีเรีย\u001Eเอกวาดอร์\u001Eเอสโตเนีย\u001Eอียิปต์\u001Eซาฮาราตะวันตก\u001Eเอริเทรีย\u001Eสเปน\u001Eเอธิโอเปีย\u001Eฟินแลนด์\u001Eฟิจิ\u001Eหมู่เกาะฟอล์กแลนด์\u001Eไมโครนีเซีย\u001Eหมู่เกาะแฟโร\u001Eฝรั่งเศส\u001Eกาบอง\u001Eสหราชอาณาจักร\u001Eเกรเนดา\u001Eจอร์เจีย\u001Eเฟรนช์เกียนา\u001Eเกิร์นซีย์\u001Eกานา\u001Eยิบรอลตาร์\u001Eกรีนแลนด์\u001Eแกมเบีย\u001Eกินี\u001Eกวาเดอลูป\u001Eอิเควทอเรียลกินี\u001Eกรีซ\u001Eเกาะเซาท์จอร์เจียและหมู่เกาะเซาท์แซนด์วิช\u001Eกัวเตมาลา\u001Eกวม\u001Eกินี-บิสเซา\u001Eกายอานา\u001Eเขตปกครองพิเศษฮ่องกงแห่งสาธารณรัฐประชาชนจีน\u001Eเกาะเฮิร์ดและหมู่เกาะแมกดอนัลด์\u001Eฮอนดูรัส\u001Eโครเอเชีย\u001Eเฮติ\u001Eฮังการี\u001Eอินโดนีเซีย\u001Eไอร์แลนด์\u001Eอิสราเอล\u001Eเกาะแมน\u001Eอินเดีย\u001Eบริติชอินเดียนโอเชียนเทร์ริทอรี\u001Eอิรัก\u001Eอิหร่าน\u001Eไอซ์แลนด์\u001Eอิตาลี\u001Eเจอร์ซีย์\u001Eจาเมกา\u001Eจอร์แดน\u001Eญี่ปุ่น\u001Eเคนยา\u001Eคีร์กีซสถาน\u001Eกัมพูชา\u001Eคิริบาส\u001Eคอโมโรส\u001Eเซนต์คิตส์และเนวิส\u001Eเกาหลีเหนือ\u001Eเกาหลีใต้\u001Eคูเวต\u001Eหมู่เกาะเคย์แมน\u001Eคาซัคสถาน\u001Eลาว\u001Eเลบานอน\u001Eเซนต์ลูเซีย\u001Eลิกเตนสไตน์\u001Eศรีลังกา\u001Eไลบีเรีย\u001Eเลโซโท\u001Eลิทัวเนีย\u001Eลักเซมเบิร์ก\u001Eลัตเวีย\u001Eลิเบีย\u001Eโมร็อกโก\u001Eโมนาโก\u001Eมอลโดวา\u001Eมอนเตเนโกร\u001Eเซนต์มาร์ติน\u001Eมาดากัสการ์\u001Eหมู่เกาะมาร์แชลล์\u001Eมาซิโดเนียเหนือ\u001Eมาลี\u001Eเมียนมา (พม่า)\u001Eมองโกเลีย\u001Eเขตปกครองพิเศษมาเก๊าแห่งสาธารณรัฐประชาชนจีน\u001Eหมู่เกาะนอร์เทิร์นมาเรียนา\u001Eมาร์ตินีก\u001Eมอริเตเนีย\u001Eมอนต์เซอร์รัต\u001Eมอลตา\u001Eมอริเชียส\u001Eมัลดีฟส์\u001Eมาลาวี\u001Eเม็กซิโก\u001Eมาเลเซีย\u001Eโมซัมบิก\u001Eนามิเบีย\u001Eนิวแคลิโดเนีย\u001Eไนเจอร์\u001Eเกาะนอร์ฟอล์ก\u001Eไนจีเรีย\u001Eนิการากัว\u001Eเนเธอร์แลนด์\u001Eนอร์เวย์\u001Eเนปาล\u001Eนาอูรู\u001Eนีอูเอ\u001Eนิวซีแลนด์\u001Eโอมาน\u001Eปานามา\u001Eเปรู\u001Eเฟรนช์โปลินีเซีย\u001Eปาปัวนิวกินี\u001Eฟิลิปปินส์\u001Eปากีสถาน\u001Eโปแลนด์\u001Eแซงปีแยร์และมีเกอลง\u001Eหมู่เกาะพิตแคร์น\u001Eเปอร์โตริโก\u001Eดินแดนปาเลสไตน์\u001Eโปรตุเกส\u001Eปาเลา\u001Eปารากวัย\u001Eกาตาร์\u001Eเรอูนียง\u001Eโรมาเนีย\u001Eเซอร์เบีย\u001Eรัสเซีย\u001Eรวันดา\u001Eซาอุดีอาระเบีย\u001Eหมู่เกาะโซโลมอน\u001Eเซเชลส์\u001Eซูดาน\u001Eสวีเดน\u001Eสิงคโปร์\u001Eเซนต์เฮเลนา\u001Eสโลวีเนีย\u001Eสฟาลบาร์และยานไมเอน\u001Eสโลวะเกีย\u001Eเซียร์ราลีโอน\u001Eซานมาริโน\u001Eเซเนกัล\u001Eโซมาเลีย\u001Eซูรินาเม\u001Eซูดานใต้\u001Eเซาตูเมและปรินซิปี\u001Eเอลซัลวาดอร์\u001Eซินต์มาร์เทน\u001Eซีเรีย\u001Eเอสวาตีนี\u001Eหมู่เกาะเติกส์และหมู่เกาะเคคอส\u001Eชาด\u001Eเฟรนช์เซาเทิร์นเทร์ริทอรีส์\u001Eโตโก\u001Eไทย\u001Eทาจิกิสถาน\u001Eโตเกเลา\u001Eติมอร์-เลสเต\u001Eเติร์กเมนิสถาน\u001Eตูนิเซีย\u001Eตองกา\u001Eตุรกี\u001Eตรินิแดดและโตเบโก\u001Eตูวาลู\u001Eไต้หวัน\u001Eแทนซาเนีย\u001Eยูเครน\u001Eยูกันดา\u001Eหมู่เกาะรอบนอกของสหรัฐอเมริกา\u001Eสหรัฐอเมริกา\u001Eอุรุกวัย\u001Eอุซเบกิสถาน\u001Eนครวาติกัน\u001Eเซนต์วินเซนต์และเกรนาดีนส์\u001Eเวเนซุเอลา\u001Eหมู่เกาะบริติชเวอร์จิน\u001Eหมู่เกาะเวอร์จินของสหรัฐอเมริกา\u001Eเวียดนาม\u001Eวานูอาตู\u001Eวาลลิสและฟุตูนา\u001Eซามัว\u001Eเยเมน\u001Eมายอต\u001Eแอฟริกาใต้\u001Eแซมเบีย\u001Eซิมบับเว"

